                    if(i == j){
                        continue;
                    }
                    Lengths[i][j] = Math.sqrt(Math.pow(Islands.get(i).GetX()-Islands.get(j).GetX(),2) + Math.pow(Islands.get(i).GetY()-Islands.get(j).GetY(),2));
                }
            }
            Kraskal();
        }
    }
